create table if not exists public.admin_help_items(id uuid primary key default gen_random_uuid(),help_key text unique not null check(help_key~'^[a-z0-9._-]{3,120}$'),title_fa text not null,body_fa text not null,title_en text not null default '',body_en text not null default '',warning_fa text,warning_en text,active boolean not null default true,updated_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.admin_help_items enable row level security;create policy admin_help_read on public.admin_help_items for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.active=true));create policy admin_help_super_write on public.admin_help_items for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.active=true and p.role='super_admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.active=true and p.role='super_admin'));insert into public.admin_help_items(help_key,title_fa,body_fa,title_en,body_en) values('projects.status','وضعیت پروژه','پیش‌نویس فقط در پنل است؛ منتشرشده در سایت دیده می‌شود؛ مخفی از سایت حذف می‌شود و زمان‌بندی‌شده در زمان تعیین‌شده قابل انتشار است.','Project status','Draft stays in admin; Published is public; Hidden is removed from public view; Scheduled is prepared for timed publishing.'),('media.alt','متن جایگزین تصویر','Alt تصویر برای دسترس‌پذیری و درک بهتر موتورهای جستجو استفاده می‌شود. کوتاه و توصیفی بنویسید.','Image alt text','Alt text improves accessibility and helps search engines understand the image. Keep it concise and descriptive.'),('security.permissions','دسترسی مدیریتی','فقط دسترسی لازم را به هر مدیر بدهید. تغییر دسترسی‌ها در Audit Log ثبت می‌شود.','Admin permissions','Grant only the permissions each administrator needs. Permission changes are recorded in the audit log.') on conflict(help_key) do nothing;
